using System;using UnityEngine;using UnityEditor;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckBuzkashi.Editor {public static class BuzProductionAuthoring {
 public static void Install(BuzMatch m){if(m.cab!=null){InstallVisibility(m.cab);return;}var cab=m.gameObject.AddComponent<BuzCabPresentation>();m.cab=cab;cab.match=m;cab.views=new SportsEventCamera[4];cab.interiors=new Transform[4];cab.look=new SportsCabLook[4];int mask=0;for(int v=0;v<4;v++)mask|=1<<(25+v);m.broadcast.view.cullingMask&=~mask;for(int v=0;v<4;v++){var c=SportsEventAuthoring.Camera("Buzkashi owned canonical cab "+v);c.view.fieldOfView=78;c.view.nearClipPlane=.025f;c.view.enabled=false;c.view.cullingMask=(~mask)|(1<<(25+v));SportsChaosAuthoring.Cab(c.view,"TruckBuzkashi",v,25);cab.views[v]=c;cab.interiors[v]=c.transform.Find("Driver seat interior");cab.interiors[v].SetParent(null,true);cab.interiors[v].gameObject.SetActive(false);cab.look[v]=c.gameObject.AddComponent<SportsCabLook>();}InstallVisibility(cab);var ring=new GameObject("Eligible loose sheep highlight").AddComponent<LineRenderer>();ring.useWorldSpace=false;ring.loop=true;ring.positionCount=48;for(int i=0;i<48;i++){float a=i*Mathf.PI*2/48;ring.SetPosition(i,new Vector3(Mathf.Cos(a)*2.2f,.025f,Mathf.Sin(a)*2.2f));}ring.startWidth=ring.endWidth=.10f;ring.sharedMaterial=SportsEventAuthoring.Mat("TruckBuzkashi","Eligible sheep cream outline",new Color(1,.88f,.2f));ring.enabled=false;cab.eligibleRing=ring;foreach(var t in m.trucks)t.steerAngle=54;EditorUtility.SetDirty(m);}
 public static void InstallVisibility(BuzCabPresentation cab){for(int v=0;v<4;v++){var mask=cab.views[v].GetComponent<LWS.TruckBowling.BowlingCabCamera>();if(mask==null)mask=cab.views[v].gameObject.AddComponent<LWS.TruckBowling.BowlingCabCamera>();mask.view=cab.views[v].view;mask.lane=null;mask.exterior=Array.Empty<Renderer>();mask.interior=cab.interiors[v].GetComponentsInChildren<Renderer>(true);EditorUtility.SetDirty(mask);}}
}}
